<script setup lang="ts">
/**
 * Notifications that report the outcome of an action (`design/components/toast.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, watch } from 'vue'

import {
  devWarning,
  getToasts,
  removeToast,
  slotNode,
  toast,
  useTrackedSlots,
  type ToastAction,
} from '@polymorph/vue'

export interface ToasterMessages {
  dismiss: string
  notification: string
  viewport: string
}

export interface ToastProps {
  /**
   * At most one; a shortcut, never the only way to do what it does.
   */
  action?: ToastAction
  description?: string
  /**
   * Required recovery actions stay reachable until their owning state resolves.
   */
  dismissible?: boolean
  /**
   * `Infinity` pins the toast until it is dismissed. A call that sets neither this nor
   * `retained` takes its tone's lifetime (see `retained`); one that sets only `retained` gets
   * `TOAST_DEFAULT_DURATION_MS`.
   */
  durationMs?: number
  /**
   * A live toast's id updates it in place: same card and position, new content, timer restarted.
   * An unknown id raises a new toast. `toast.promise` uses this, not a special path.
   */
  id?: string
  /**
   * State-owned notices are removed by their owner, never evicted by another notification. A
   * call that sets neither this nor `durationMs` takes its tone's lifetime: danger and warning
   * are retained and pinned, and the other tones leave after the default duration.
   */
  retained?: boolean
  title: string
  tone?: 'info' | 'warning' | 'success' | 'danger' | 'neutral'
}

defineOptions({ name: 'Toast', inheritAttrs: false })

const props = withDefaults(defineProps<ToastProps>(), {
  dismissible: undefined,
  retained: undefined,
})
const emit = defineEmits<{ dismiss: [] }>()
const callerSlots = defineSlots<{ content?: (props: Record<string, never>) => unknown }>()
const slots = useTrackedSlots(callerSlots)
const uid = useId()
const toastId = computed(() => props.id ?? uid)
const options = computed(() => ({
  id: toastId.value,
  title: props.title,
  description: props.description,
  tone: props.tone,
  action: props.action,
  durationMs: props.durationMs,
  dismissible: props.dismissible,
  retained: props.retained,
  content: slotNode(slots.content),
  onDismiss: () => emit('dismiss'),
}))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = toast(options.value)
  release1 = () => {
    removeToast(ran)
  }
}
onMounted(effect1)
watch(() => [toastId.value, props.title], effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  getToasts().some((record) => record.id === toastId.value && record.closing !== true) &&
    toast(options.value)
}
watch(() => options.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const timer = setTimeout(() => {
    devWarning(
      document.querySelector('[data-toast-part="list"]') === null,
      `Toast "${props.title}" rendered with no Toast viewport mounted, so nothing draws it. Mount the viewport once at the application root, outside any error boundary whose fallback renders a Toast.`,
    )
  }, 0)
  release3 = () => clearTimeout(timer)
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <template v-if="false" />
</template>
